mapper.select:
SELECT COUNT(1)
FROM exp_account
WHERE account_name = #{accountName}

    AND account_id != #{excludeAccountId}

SELECT ra.principal_id as accountId, r.role_id as roleId, r.role_name as roleName, r.role_code as roleCode FROM exp_role_assign ra INNER JOIN exp_role r ON ra.role_id = r.role_id WHERE ra.principal_type = 'ACCOUNT' AND ra.status = 'ENABLED' AND r.status = 'ENABLED' AND (ra.start_time IS NULL OR ra.start_time <= NOW()) AND (ra.end_time IS NULL OR ra.end_time >= NOW()) AND ra.principal_id IN
#{accountId}
ORDER BY ra.principal_id, r.sort_no

